from solution import *  # added by harness
import pytest

def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fib(n - 1) + fib(n - 2)

@pytest.mark.parametrize("n, expected", [(10, 55), (1, 1), (8, 21)])
def test_fib(n, expected):
    assert fib(n) == expected

